import { BigNumber, ChartHeader, DataStateHandler } from 'components';
import type { BigNumbersKpiData } from 'pages/pillars/PortfolioBrand/BrandPowerBookExport/types';

import { StyledBrandPowerBigNumbers } from './BrandPowerBigNumbers.styles';

interface BigNumbersProps {
  loading: boolean;
  error: Error | null;
  empty?: boolean;
  powerVsLq?: BigNumbersKpiData;
  powerVsLy?: BigNumbersKpiData;
  selectedPeriodType?: string;
  dataTestId?: string;
}

export const BrandPowerBigNumbers = ({
  loading,
  error,
  empty = false,
  powerVsLq,
  powerVsLy,
  selectedPeriodType,
  dataTestId,
}: BigNumbersProps) => {
  const isYtd =
    powerVsLy?.periodType === 'YTD' ||
    selectedPeriodType?.toUpperCase() === 'YTD';
  const skeletonWidth = isYtd ? '100%' : 'calc((100% - 16px) / 2)';
  const cards = [
    { key: 'ly', data: powerVsLy },
    ...(isYtd ? [] : [{ key: 'lq', data: powerVsLq }]),
  ];
  const hasNoVisibleData =
    cards.length > 0 && cards.every((card) => card.data?.empty);

  return (
    <StyledBrandPowerBigNumbers $isYtd={isYtd} data-testid={dataTestId}>
      <DataStateHandler
        loading={loading}
        error={error}
        skeletonProps={{
          height: '100%',
          width: skeletonWidth,
          length: isYtd ? 1 : 2,
          gap: 'medium',
        }}
        empty={empty || hasNoVisibleData}
      >
        {cards.map((card) => (
          <BigNumber
            key={card.key}
            data={card.data?.data || []}
            header={
              <ChartHeader
                title={card.data?.header?.title}
                config={{ inline: 'vertical', type: 'small' }}
              />
            }
            asCard
            fullWidth
            alignment="left"
            className={isYtd ? 'brand-power-big-number-ytd' : undefined}
          />
        ))}
      </DataStateHandler>
    </StyledBrandPowerBigNumbers>
  );
};
